INMI = [("1881–90", 5.2), ("1891–00", 3.7), ("1901–10", 8.8), ("1911–20", 5.7), ("1921–30", 4.1), ("1931–40", 0.5), ("1941–50", 1.0)]


def titulo():
    return t("From the 20th century to today: industrialization, wars, and civil rights", "Del siglo XX a hoy: industrialización, guerras y derechos civiles")


def graf_inmi():
    spec = {"tipo": "barras", "xEtq": t("Decade", "Década"), "yEtq": t("Millions of people admitted", "Millones de personas admitidas"),
            "barras": [{"etq": a, "valor": v, "txt": f"{v:.1f}"} for a, v in INMI]}
    return C.grafica(spec, C.describe(spec), ancho=620, alto=320, y0=0, y1=10)


def estrategia(icono, nombre, doc, texto, logro, limite):
    filas = "".join(f"<tr><td>{a}</td><td>{b}</td></tr>" for a, b in zip(logro, limite + [""] * (len(logro) - len(limite))))
    return (f'<h3><span aria-hidden="true">{icono}</span> {nombre}</h3>{doc}<p>{texto}</p>' +
            C.tabla(t("What it achieved and what it could not do", "Qué logró y qué no pudo"), [t("What it achieved", "Qué logró"), t("What it could not do", "Qué no pudo")], [[a, b] for a, b in zip(logro, limite)]))


